/**
 * List the configuration ownership of one resource kind
 *
 * Lets screens lock file-managed resources before a change fails with 409. Besides `tenant:admin` and `tenants:manage`, it accepts the roles that change the kind through the management API, for example `issuance:manage` for `CredentialConfig` or `presentation:manage` for `PresentationConfig`.
 */
export const configPortabilityControllerResourcesOfKind = <ThrowOnError extends boolean = true>(options: Options<ConfigPortabilityControllerResourcesOfKindData, ThrowOnError>): RequestResult<ConfigPortabilityControllerResourcesOfKindResponses, ConfigPortabilityControllerResourcesOfKindErrors, ThrowOnError> => (options.client ?? client).get<ConfigPortabilityControllerResourcesOfKindResponses, ConfigPortabilityControllerResourcesOfKindErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/api/config-bundles/resources/{kind}',
    ...options
});

/**
 * Export one resource as a configuration document
 *
 * Returns the resource as a `$schema` and `spec` document in the current format version, the format of the files in the config folder and of the documents in a configuration bundle. Secrets are `${PLACEHOLDER}` references, as in the bundle export, and image references name the file. A key chain held in the database keeps its private keys, for a CA chain also the signing key, which `GET /key-chain/{id}/export` leaves out, so a `KeyChain` document needs `tenant:admin` or `tenants:manage`. Other kinds accept the roles that change them through the management API, for example `issuance:manage` for `CredentialConfig` and `keys:manage` for `KeyChainDefaults`. Singleton kinds use their fixed ID: `tenant`, `kms`, `issuance` and `defaults`.
 */
export const configPortabilityControllerExportDocument = <ThrowOnError extends boolean = true>(options: Options<ConfigPortabilityControllerExportDocumentData, ThrowOnError>): RequestResult<ConfigPortabilityControllerExportDocumentResponses, ConfigPortabilityControllerExportDocumentErrors, ThrowOnError> => (options.client ?? client).get<ConfigPortabilityControllerExportDocumentResponses, ConfigPortabilityControllerExportDocumentErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/api/config-bundles/resources/{kind}/{id}/document',
    ...options
});

